public class Main {
  public static void main(String[] args) {
    int[] arr = {1, 2, 3, 4};
    // En Java el tipo se conoce en tiempo de compilación (int[])
    System.out.println(arr.getClass().getSimpleName()); // int[]
  }
}

// En Java se declara explícitamente el tipo de dato
String[] arr = {"1", "2", "3", "4"};
System.out.println(java.util.Arrays.toString(arr));

double[] arr = {1.1, 2.1, 3.1};
int[] nuevoarr = new int[arr.length];

// Java obliga a iterar y castear elemento por elemento
for (int i = 0; i < arr.length; i++) {
    nuevoarr[i] = (int) arr[i];
}
System.out.println(java.util.Arrays.toString(nuevoarr));
